cpp.code:
void printN(int n) {
    if (n == 0) return;
    printN(n - 1);
    cout << n << " ";
}

java.code:
static void printN(int n) {
    if (n == 0) return;
    printN(n - 1);
    System.out.print(n + " ");
}

go.code:
func printN(n int) {
    if n == 0 { return }
    printN(n - 1)
    fmt.Print(n, " ")
}
